      hu: ["Óraváros", "UNESCO-világörökség", "Jura-hegység", "Neuchâtel"],
      ro: ["Orașul ceasurilor", "Patrimoniu UNESCO", "Munții Jura", "Neuchâtel"],
      en: ["Watch city", "UNESCO World Heritage", "Jura mountains", "Neuchâtel"],
      es: ["Ciudad relojera", "Patrimonio de la Humanidad por la UNESCO", "Jura", "Neuchâtel"],
